21	rbtree_t *rb_create(rb_value_free_fn value_free)
22	{
23	    rbtree_t *t = rb_malloc(sizeof *t);
24	    if (!t)
25	        return NULL;                 /* nothing allocated yet, nothing to free */
26	
27	    rbnode_t *nil = rb_malloc(sizeof *nil);
28	    if (!nil)
29	        goto cleanup_tree;           /* second alloc failed, unwind the first */
30	
31	    nil->color  = RB_BLACK;
32	    nil->key    = NULL;
33	    nil->value  = NULL;
34	    nil->left = nil->right = nil->parent = nil;
35	
36	    t->nil        = nil;
37	    t->root        = nil;
38	    t->size        = 0;
39	    t->value_free = value_free;
40	    return t;
41	
42	cleanup_tree:
43	    rb_free(t);
44	    return NULL;
45	}
