47	static void rb_rotate_left(rbtree_t *t, rbnode_t *nodeToRotate)
48	{
49	    rbnode_t *rightChild = nodeToRotate->right;
50	    nodeToRotate->right = rightChild->left;
51	    if (rightChild->left != t->nil)
52	        rightChild->left->parent = nodeToRotate;
53	
54	    rightChild->parent = nodeToRotate->parent;
55	    if (nodeToRotate->parent == t->nil)
56	        t->root = rightChild;
57	    else if (nodeToRotate == nodeToRotate->parent->left)
58	        nodeToRotate->parent->left = rightChild;
59	    else
60	        nodeToRotate->parent->right = rightChild;
61	
62	    rightChild->left = nodeToRotate;
63	    nodeToRotate->parent = rightChild;
64	}
65	
66	static void rb_rotate_right(rbtree_t *t, rbnode_t *nodeToRotate)
67	{
68	    rbnode_t *leftChild = nodeToRotate->left;
69	    nodeToRotate->left = leftChild->right;
70	    if (leftChild->right != t->nil)
71	        leftChild->right->parent = nodeToRotate;
72	
73	    leftChild->parent = nodeToRotate->parent;
74	    if (nodeToRotate->parent == t->nil)
75	        t->root = leftChild;
76	    else if (nodeToRotate == nodeToRotate->parent->right)
77	        nodeToRotate->parent->right = leftChild;
78	    else
79	        nodeToRotate->parent->left = leftChild;
80	
81	    leftChild->right = nodeToRotate;
82	    nodeToRotate->parent = leftChild;
83	}
