85	/* Replaces the subtree rooted at oldSubtree with newSubtree in oldSubtree's
86	 * parent (or t->root if it was the root), and repoints newSubtree->parent.
87	 * newSubtree may be t->nil. */
88	static void rb_splice(rbtree_t *t, rbnode_t *oldSubtree, rbnode_t *newSubtree)
89	{
90	    if (oldSubtree->parent == t->nil)
91	        t->root = newSubtree;
92	    else if (oldSubtree == oldSubtree->parent->left)
93	        oldSubtree->parent->left = newSubtree;
94	    else
95	        oldSubtree->parent->right = newSubtree;
96	
97	    newSubtree->parent = oldSubtree->parent;
98	}
