113	int rb_insert(rbtree_t *t, const char *key, void *value)
114	{
115	    rbnode_t *cur = t->root;
116	    rbnode_t *parent = t->nil;
117	    int cmp = 0;
118	
119	    /* invariant: cur is the subtree still to search; parent trails one node
120	     * behind as the eventual new node's parent (or the overwrite target)
121	     * once cur reaches nil or an exact match. */
122	    while (cur != t->nil) {
123	        cmp = strcmp(key, cur->key);
124	        if (cmp == 0) {
125	            if (t->value_free)
126	                t->value_free(cur->value);
127	            cur->value = value;
128	            return 0;
129	        }
130	        parent = cur;
131	        cur = (cmp < 0) ? cur->left : cur->right;
132	    }
133	
134	    rbnode_t *n = rb_malloc(sizeof *n);
135	    if (!n) return -1;                   /* nothing allocated yet, nothing to free */
136	
137	    size_t klen = strlen(key) + 1;
138	    char *kcopy = rb_malloc(klen);
139	    if (!kcopy) goto cleanup_node;           /* second alloc failed, unwind the first */
140	    memcpy(kcopy, key, klen);
141	
142	    n->key    = kcopy;
143	    n->value  = value;
144	    n->left   = n->right = t->nil;
145	    n->parent = parent;
146	    n->color  = RB_RED;
147	
148	    if (parent == t->nil) {
149	        t->root = n;
150	    } else if (cmp < 0) {
151	        parent->left = n;
152	    } else {
153	        parent->right = n;
154	    }
155	    
156	
157	    /* TODO: red-black fixup. A fresh non-root node inserted red can now
158	     * have a red parent, which rb_validate will reject until fixup lands. */
159	
160	    rbnode_t *problemNode = n;
161	    while (problemNode->parent->color == RB_RED) {
162	        if (problemNode->parent == problemNode->parent->parent->left) {
163	            rbnode_t *uncle = problemNode->parent->parent->right;  
164	            if (uncle->color == RB_RED) {
165	                // Case 1
166	                problemNode->parent->color = RB_BLACK;
167	                uncle->color = RB_BLACK;
168	                problemNode->parent->parent->color = RB_RED;
169	                problemNode = problemNode->parent->parent;
170	            } else {
171	                if (problemNode == problemNode->parent->right) {
172	                    // Case 2
173	                    problemNode = problemNode->parent;
174	                    rb_rotate_left(t, problemNode);
175	                }
176	                // Case 3
177	                problemNode->parent->color = RB_BLACK;
178	                problemNode->parent->parent->color = RB_RED;
179	                rb_rotate_right(t, problemNode->parent->parent);
180	            }
181	        } else {
182	            // (mirror image, swap left/right)
183	            rbnode_t *uncle = problemNode->parent->parent->left;
184	            if (uncle->color == RB_RED) {
185	                // Case 1
186	                problemNode->parent->color = RB_BLACK;
187	                uncle->color = RB_BLACK;
188	                problemNode->parent->parent->color = RB_RED;
189	                problemNode = problemNode->parent->parent;
190	            } else {
191	                if (problemNode == problemNode->parent->left) {
192	                    // Case 2
193	                    problemNode = problemNode->parent;
194	                    rb_rotate_right(t, problemNode);
195	                }
196	                // Case 3
197	                problemNode->parent->color = RB_BLACK;
198	                problemNode->parent->parent->color = RB_RED;
199	                rb_rotate_left(t, problemNode->parent->parent);
200	            }
201	        }
202	    }
203	    t->root->color = RB_BLACK;
204	    t->size++;
205	    return 0;
206	
207	cleanup_node:
208	    rb_free(n);
209	    return -1;
210	}
211	
212	size_t rb_size(const rbtree_t *t)
213	{
214	    return t->size;
215	}
