217	void *rb_find(const rbtree_t *t, const char *key)
218	{
219	    rbnode_t *cur = t->root;
220	
221	    /* invariant: cur is the subtree still to search; strcmp narrows left or
222	     * right each step until an exact match or the nil sentinel is reached. */
223	    while (cur != t->nil) {
224	        int cmp = strcmp(key, cur->key);
225	        if (cmp == 0)
226	            return cur->value;
227	        cur = (cmp < 0) ? cur->left : cur->right;
228	    }
229	    return NULL;
230	}
