232	int rb_delete(rbtree_t *t, const char *key)
233	{
234	    rbnode_t *target = t->root;
235	
236	    /* invariant: target is the subtree still to search; strcmp narrows left
237	     * or right each step until an exact match or the nil sentinel is
238	     * reached (same search as rb_find). */
239	    while (target != t->nil) {
240	        int cmp = strcmp(key, target->key);
241	        if (cmp == 0)
242	            break;
243	        target = (cmp < 0) ? target->left : target->right;
244	    }
245	
246	    if (target == t->nil)
247	        return -1;                    /* absent; tree unchanged */
248	
249	    rbnode_t *removedColorNode = target;  /* node whose original color is leaving the tree */
250	    int removedColor = removedColorNode->color;
251	    rbnode_t *fixNode;                    /* node that inherits any missing black */
252	
253	    if (target->left == t->nil) {
254	        fixNode = target->right;
255	        rb_splice(t, target, target->right);
256	    } else if (target->right == t->nil) {
257	        fixNode = target->left;
258	        rb_splice(t, target, target->left);
259	    } else {
260	        removedColorNode = rb_inorder_successor(t, target->right);
261	        removedColor = removedColorNode->color;
262	        fixNode = removedColorNode->right;
263	
264	        if (removedColorNode->parent == target) {
265	            fixNode->parent = removedColorNode;   /* rb_splice is skipped below, so set this by hand */
266	        } else {
267	            rb_splice(t, removedColorNode, removedColorNode->right);
268	            removedColorNode->right = target->right;
269	            removedColorNode->right->parent = removedColorNode;
270	        }
271	
272	        rb_splice(t, target, removedColorNode);
273	        removedColorNode->left = target->left;
274	        removedColorNode->left->parent = removedColorNode;
275	        removedColorNode->color = target->color;   /* successor takes target's color/position */
276	    }
277	
278	    if (removedColor == RB_BLACK) {
279	        /* invariant: fixNode carries an extra black that must be resolved
280	         * before this loop exits; each pass either absorbs it via a
281	         * terminal rotation (case 4) or pushes it one level up (case 2). */
282	        while (fixNode != t->root && fixNode->color == RB_BLACK) {
283	            if (fixNode == fixNode->parent->left) {
284	                rbnode_t *sibling = fixNode->parent->right;
285	                if (sibling->color == RB_RED) {
286	                    // Case 1
287	                    sibling->color = RB_BLACK;
288	                    fixNode->parent->color = RB_RED;
289	                    rb_rotate_left(t, fixNode->parent);
290	                    sibling = fixNode->parent->right;
291	                }
292	                if (sibling->left->color == RB_BLACK && sibling->right->color == RB_BLACK) {
293	                    // Case 2
294	                    if (sibling != t->nil)   /* t->nil is an immutable black constant */
295	                        sibling->color = RB_RED;
296	                    fixNode = fixNode->parent;
297	                } else {
298	                    if (sibling->right->color == RB_BLACK) {
299	                        // Case 3
300	                        sibling->left->color = RB_BLACK;
301	                        sibling->color = RB_RED;
302	                        rb_rotate_right(t, sibling);
303	                        sibling = fixNode->parent->right;
304	                    }
305	                    // Case 4
306	                    sibling->color = fixNode->parent->color;
307	                    fixNode->parent->color = RB_BLACK;
308	                    sibling->right->color = RB_BLACK;
309	                    rb_rotate_left(t, fixNode->parent);
310	                    fixNode = t->root;
311	                }
312	            } else {
313	                // (mirror image, swap left/right)
314	                rbnode_t *sibling = fixNode->parent->left;
315	                if (sibling->color == RB_RED) {
316	                    // Case 1
317	                    sibling->color = RB_BLACK;
318	                    fixNode->parent->color = RB_RED;
319	                    rb_rotate_right(t, fixNode->parent);
320	                    sibling = fixNode->parent->left;
321	                }
322	                if (sibling->right->color == RB_BLACK && sibling->left->color == RB_BLACK) {
323	                    // Case 2
324	                    if (sibling != t->nil)   /* t->nil is an immutable black constant */
325	                        sibling->color = RB_RED;
326	                    fixNode = fixNode->parent;
327	                } else {
328	                    if (sibling->left->color == RB_BLACK) {
329	                        // Case 3
330	                        sibling->right->color = RB_BLACK;
331	                        sibling->color = RB_RED;
332	                        rb_rotate_left(t, sibling);
333	                        sibling = fixNode->parent->left;
334	                    }
335	                    // Case 4
336	                    sibling->color = fixNode->parent->color;
337	                    fixNode->parent->color = RB_BLACK;
338	                    sibling->left->color = RB_BLACK;
339	                    rb_rotate_right(t, fixNode->parent);
340	                    fixNode = t->root;
341	                }
342	            }
343	        }
344	        fixNode->color = RB_BLACK;
345	    }
346	
347	    if (t->value_free)
348	        t->value_free(target->value);
349	    rb_free(target->key);
350	    rb_free(target);
351	    t->size--;
352	    return 0;
353	}
354	
355	static void rb_foreach_helper(const rbtree_t *t, rbnode_t *checkNode, void (*callerFunction)(const char *key, void *value, void *callerFunctionContext), void (*callerFunctionContext)) {
356	    if (checkNode == t-> nil) return; // Terminate at t->nil
357	    rb_foreach_helper(t, checkNode->left, callerFunction, callerFunctionContext); // Recurse left first (inorder)
358	    callerFunction(checkNode->key, checkNode->value, callerFunctionContext); // Run callerFunction to give them their output
359	    rb_foreach_helper(t, checkNode->right, callerFunction, callerFunctionContext); // Recurse right last (no more left descendants in subtree)
360	}
361	
362	void rb_foreach(const rbtree_t *t,
363	                void (*callerFunction)(const char *key, void *value, void *callerFunctionContext),
364	                void *callerFunctionContext)
365	{
366	    /* TODO: in-order traversal, stopping at t->nil. */
367	    rb_foreach_helper(t, t->root, callerFunction, callerFunctionContext);
368	}
369	
370	/* Checks order, no-red-red, and black-height for the subtree rooted at x;
371	 * reports 1/0 and writes that subtree's black-height to *bh. lo/hi are the
372	 * open key bound threaded down from ancestors (NULL = unbounded), which is
373	 * what catches an order violation against a distant ancestor, not just x's
374	 * immediate parent. */
375	static int rb_validate_node(const rbtree_t *t, const rbnode_t *x,
376	                             const char *lo, const char *hi, int *bh)
377	{
378	    if (x == t->nil) {
379	        *bh = 0;
380	        return 1;
381	    }
382	
383	    if (lo && strcmp(x->key, lo) <= 0)
384	        return 0;
385	    if (hi && strcmp(x->key, hi) >= 0)
386	        return 0;
387	
388	    if (x->color == RB_RED &&
389	        (x->left->color == RB_RED || x->right->color == RB_RED))
390	        return 0;
391	
392	    int bhL, bhR;
393	    if (!rb_validate_node(t, x->left, lo, x->key, &bhL))
394	        return 0;
395	    if (!rb_validate_node(t, x->right, x->key, hi, &bhR))
396	        return 0;
397	    if (bhL != bhR)
398	        return 0;
399	
400	    *bh = bhL + (x->color == RB_BLACK ? 1 : 0);
401	    return 1;
402	}
403	
404	int rb_validate(const rbtree_t *t)
405	{
406	    if (t->root->color != RB_BLACK)
407	        return -1;
408	
409	    int bh;
410	    return rb_validate_node(t, t->root, NULL, NULL, &bh) ? 0 : -1;
411	}
412	
413	/* Post-order: free a node's children before the node itself, so no pointer
414	 * into freed memory is ever dereferenced. Stops at t->nil, the shared
415	 * sentinel, which rb_destroy frees separately, once, after this returns. */
416	static void rb_destroy_node(rbtree_t *t, rbnode_t *n)
417	{
418	    if (n == t->nil)
419	        return;
420	    rb_destroy_node(t, n->left);
421	    rb_destroy_node(t, n->right);
422	    if (t->value_free)
423	        t->value_free(n->value);
424	    rb_free(n->key);
425	    rb_free(n);
426	}
427	
428	void rb_destroy(rbtree_t *t)
429	{
430	    if (!t)
431	        return;
432	    rb_destroy_node(t, t->root);
433	    rb_free(t->nil);
434	    rb_free(t);
435	}

