        if (i % VALIDATE_INTERVAL == 0) {
            assert(rb_validate(t) == 0);
            check_foreach(t);
        }
    }

    assert(rb_validate(t) == 0);
    check_foreach(t);
    rb_destroy(t);

    for (int i = 0; i < KEYSPACE; i++)
        rb_free(key_pool[i]);

    printf("ok - fuzz: %ld ops, seed %u\n", ops, seed);
    return 0;
}
```

